#!/usr/bin/env python3
"""Builds the Ascend Android project from the flat files in this repo.
Run by the GitHub workflow: creates the Capacitor Android project, then adds the Today widget."""
import base64, os, re, shutil, subprocess, sys

FILES = {
    'java/com/ascend/habits/MainActivity.java': '',
    'java/com/ascend/habits/TapReceiver.java': '',
    'java/com/ascend/habits/TodayWidgetProvider.java': '',
    'java/com/ascend/habits/TodayWidgetService.java': '',
    'java/com/ascend/habits/WidgetBridgePlugin.java': '',
    'java/com/ascend/habits/WidgetStore.java': '',
    'res/layout/widget_row.xml': '',
    'res/layout/widget_row_bold.xml': '',
    'res/layout/widget_sep.xml': '',
    'res/layout/widget_today.xml': '',
    'res/drawable/widget_add.xml': 'PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0idXRmLTgiPz4KPHNoYXBlIHhtbG5zOmFuZHJvaWQ9Imh0dHA6Ly9zY2hlbWFzLmFuZHJvaWQuY29tL2Fway9yZXMvYW5kcm9pZCIgYW5kcm9pZDpzaGFwZT0ib3ZhbCI+CiAgICA8c29saWQgYW5kcm9pZDpjb2xvcj0iI0M5QTIyNyIgLz4KPC9zaGFwZT4K',
    'res/drawable/widget_bg.xml': '',
    'res/drawable/widget_check_off.xml': '',
    'res/drawable/widget_check_on.xml': 'PD94bWwgdmVyc2lvbj0iMS4wIiBlbmNvZGluZz0idXRmLTgiPz4KPHNoYXBlIHhtbG5zOmFuZHJvaWQ9Imh0dHA6Ly9zY2hlbWFzLmFuZHJvaWQuY29tL2Fway9yZXMvYW5kcm9pZCIgYW5kcm9pZDpzaGFwZT0ib3ZhbCI+CiAgICA8c29saWQgYW5kcm9pZDpjb2xvcj0iIzdGQTg3MiIgLz4KPC9zaGFwZT4K',
    'res/drawable/widget_row_bg.xml': '',
    'res/xml/today_widget_info.xml': '',
}

MAIN = 'android/app/src/main/'

def run(*cmd):
    print('>', ' '.join(cmd)); subprocess.check_call(cmd)

# 1. web files -> www/
os.makedirs('www', exist_ok=True)
for f in ['index.html','manifest.json','icon-192.png','icon-512.png','icon-maskable-192.png','icon-maskable-512.png']:
    shutil.copy(f, os.path.join('www', f))

# address of the website copy (GitHub Pages) that the app checks for updates
repo = os.environ.get('GITHUB_REPOSITORY', '')
if '/' in repo:
    owner, name = repo.split('/', 1)
    update_url = 'https://%s.github.io/%s/index.html' % (owner.lower(), name)
    html = open('www/index.html', encoding='utf-8').read()
    open('www/index.html', 'w', encoding='utf-8').write(html.replace("'__UPDATE_URL__'", "'" + update_url + "'"))
    print('Update address:', update_url)

# 2. create the Android project
if not os.path.isdir('android'):
    run('npx', 'cap', 'add', 'android')

# 3. widget sources and resources
for rel, b64 in FILES.items():
    path = MAIN + rel
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as fh:
        fh.write(base64.b64decode(b64))

# 4. strings, launcher background colour
p = MAIN + 'res/values/strings.xml'
s = open(p, encoding='utf-8').read()
if 'widget_description' not in s:
    s = s.replace('</resources>', "    <string name=\"widget_description\">Habits, challenges and tasks for today. Tap to complete.</string>\n</resources>")
open(p, 'w', encoding='utf-8').write(s)
p = MAIN + 'res/values/ic_launcher_background.xml'
bg = open(p, encoding='utf-8').read().replace('#FFFFFF', '#12160F')
open(p, 'w', encoding='utf-8').write(bg)

# 5. manifest: register widget, tap receiver and list service
p = MAIN + 'AndroidManifest.xml'
s = open(p, encoding='utf-8').read()
if 'TodayWidgetProvider' not in s:
    add = """
        <receiver
            android:name=".TodayWidgetProvider"
            android:exported="true">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/today_widget_info" />
        </receiver>

        <receiver
            android:name=".TapReceiver"
            android:exported="false" />

        <service
            android:name=".TodayWidgetService"
            android:exported="false"
            android:permission="android.permission.BIND_REMOTEVIEWS" />
"""
    s = s.replace('    </application>', add + '    </application>')
open(p, 'w', encoding='utf-8').write(s)

# 5b. fixed signing key (so every build can be installed over the previous one) + increasing version number
if not os.path.exists('ascend.keystore'):
    sys.exit('ascend.keystore is missing. Add the KEYSTORE_BASE64 secret in the repo settings (see the instructions).')
shutil.copy('ascend.keystore', 'android/app/ascend.keystore')
p = 'android/app/build.gradle'
g = open(p, encoding='utf-8').read()
if 'signingConfigs' not in g:
    g = g.replace('    buildTypes {', """    signingConfigs {
        debug {
            storeFile file('ascend.keystore')
            storePassword 'tAQFAVogDJehLq6vOxJcZajK'
            keyAlias 'ascend'
            keyPassword 'tAQFAVogDJehLq6vOxJcZajK'
        }
    }
    buildTypes {""", 1)
run_no = os.environ.get('GITHUB_RUN_NUMBER', '1')
g = g.replace('versionCode 1', 'versionCode ' + run_no, 1).replace('versionName "1.0"', 'versionName "1.' + run_no + '"', 1)
open(p, 'w', encoding='utf-8').write(g)

# 6. launcher icons from icon-512.png
from PIL import Image
src = Image.open('icon-512.png').convert('RGBA')
for d, l, f in (('mdpi',48,108),('hdpi',72,162),('xhdpi',96,216),('xxhdpi',144,324),('xxxhdpi',192,432)):
    base = MAIN + 'res/mipmap-%s/' % d
    ic = src.resize((l, l), Image.LANCZOS)
    ic.save(base + 'ic_launcher.png'); ic.save(base + 'ic_launcher_round.png')
    k = int(f * 0.56)
    canvas = Image.new('RGBA', (f, f), (0, 0, 0, 0))
    canvas.paste(src.resize((k, k), Image.LANCZOS), ((f - k) // 2, (f - k) // 2))
    canvas.save(base + 'ic_launcher_foreground.png')

print('Android project ready.')
